fn fixture()->SemioObjectSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let target=|i:usize|store::os_io::ArtifactRef{artifact_id:f["children"][i][0].as_str().unwrap().into(),dialect:store::os_io::ArtifactDialect{artifact_kind:f["children"][i][1].as_str().unwrap().into(),standard:f["children"][i][2].as_str().unwrap().into(),subset:f["children"][i][3].as_str().unwrap().into()}};let mut value=SemioObjectSnapshot::default();value.transform.translation.x=f["translation"][0].as_f64().unwrap();value.transform.translation.y=f["translation"][1].as_f64().unwrap();value.transform.translation.z=f["translation"][2].as_f64().unwrap();value.transform.scale.x=-1.0;value.transform.scale.y=2.0;value.transform.scale.z=0.5;value.brep=Some(store::ArtifactChild::new("brep-owned".into(),target(0)));value.mesh=Some(store::ArtifactChild::new("mesh-owned".into(),target(1)));value.properties=Some(store::ArtifactChild::new("value-owned".into(),target(2)));value}
