fn sqlite_snapshot_semio_object_all_transform_fields_erased_word_state(){let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let words=f["transformBits"].as_array().unwrap();assert_eq!(words.len(),10);let provider=store::ArtifactCodec::bare::<SemioObjectSnapshot,crate::standards::v1::subsets::object::schema::mutations::SemioObjectMutation>("s.stdio.semio.object").snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"object".into()};for offset in 0..words.len(){let mut s=fixture();let t=&mut s.transform;for(index,field)in [&mut t.translation.x,&mut t.translation.y,&mut t.translation.z,&mut t.rotation.x,&mut t.rotation.y,&mut t.rotation.z,&mut t.rotation.w,&mut t.scale.x,&mut t.scale.y,&mut t.scale.z].into_iter().enumerate(){*field=f64::from_bits(u64::from_str_radix(words[(index+offset)%words.len()].as_str().unwrap(),16).unwrap());}for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&s))};let db=(provider.export)("s.stdio.semio.object",&dialect,&expected,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.object",&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,expected,"field word rotation {offset} {encoding:?}");}}}

